  ["Invalid value for parameter %s"] = "Valor inválido para parâmetro %s",
  ["Parameter 1: 1 represents enable, 0 or other: represents disable"] = "Parâmetro 1: 1 representa habilitação, 0 ou outro: representa desabilitação",
  ["Parameter 1: 1 represents enable, 0 or other: represents disable (execute after entering game)"] = "Parâmetro 1: 1 representa habilitar, 0 ou outro: representa desabilitar (executar após entrar no jogo)",
  ["Parameter 1: 3 for 3v3, 5 for 12v12, 6 for 6v6; Parameter 2: number 1-20."] = "Parâmetro 1: 3 para 3v3, 5 para 12v12, 6 para 6v6; Parâmetro 2: número 1-20.",
  ["Parameter 1: distance scale, multiplier for capsule half-height, default is 2."] = "Parâmetro 1: escala de distância, multiplicador para meia altura da cápsula, o padrão é 2.",
  ["Param 1: Connection ID; Param 2: Affinity EXP"] = "Parâmetro 1: ID de conexão; Parâmetro 2: EXP de afinidade",
  ["Parameter 1: offset; the queue number displayed on the client will be the real number + offset."] = "Parâmetro 1: deslocamento; o número da fila exibido no cliente será o número real + deslocamento.",
  ["Param 1: Cult ID, Param 2: Exploration Attribute."] = "Parâmetro 1: ID do culto, Parâmetro 2: Atributo de exploração.",
  ["Parameter 1: enable default material; 1: enable, 0: disable."] = "Parâmetro 1: habilitar material padrão; 1: habilitar, 0: desabilitar.",
  ["Parameter 1: Estimated number of people logging out per minute, set to 0 to clear setting"] = "Parâmetro 1: Número estimado de pessoas desconectadas por minuto, definido como 0 para limpar a configuração",
  ["Parameter 1: source map ID (map or plane), parameter 2: target map ID (map or plane), parameter 3: Group name to migrate (space-separated)."] = "Parâmetro 1: ID do mapa de origem (mapa ou plano), parâmetro 2: ID do mapa de destino (mapa ou plano), parâmetro 3: Nome do grupo a ser migrado (separado por espaço).",
  ["Parameter 1: Battery percentage 0-100, Parameter 2: Is charging, 1 represents enable, 0 or other: represents disable"] = "Parâmetro 1: Porcentagem da bateria 0-100, Parâmetro 2: Está carregando, 1 representa habilitação, 0 ou outro: representa desabilitação",
  ["Parameter 1: config key, parameter 2: config val; e.g., configSoftLimit 20."] = "Parâmetro 1: chave de configuração, parâmetro 2: config val; por exemplo, configSoftLimit 20.",
  ["Parameter 1: TipsID."] = "Parâmetro 1: TipsID.",
