  ["Param 1: Shard ID, Param 2: Shard type"] = "Parâmetro 1: ID do fragmento, Parâmetro 2: tipo de fragmento",
  ["Param 1: Shard ID, Param 2: Number of bots"] = "Parâmetro 1: ID do fragmento, Parâmetro 2: Número de bots",
  ["Parameter 1: scene index (0: selection field, 1-8: corresponding board), 2-4: relative coordinates X, Y, Z, 5: pitch, 6: yaw."] = "Parâmetro 1: índice de cena (0: campo de seleção, 1-8: placa correspondente), 2-4: coordenadas relativas X, Y, Z, 5: inclinação, 6: guinada.",
  ["Parameter 1: talent ID."] = "Parâmetro 1: ID do talento.",
  ["Parameter 1: piece ID (random if blank)."] = "Parâmetro 1: ID da peça (aleatório se estiver em branco).",
  ["Param 1: Board index (1-8), Param 2: Is host position (1 for yes, other values for no)."] = "Parâmetro 1: Índice do conselho (1-8), Parâmetro 2: É a posição do host (1 para sim, outros valores para não).",
  ["Param 1: Equipment ID."] = "Parâmetro 1: ID do equipamento.",
  ["Param 1: Gold Coin amount."] = "Parâmetro 1: Valor da moeda de ouro.",
  ["Parameter 1: instanceID, parameter 2: Icon style, parameter 3: scale multiplier, parameter 4: scale time (seconds)."] = "Parâmetro 1: instanceID, parâmetro 2: estilo do ícone, parâmetro 3: multiplicador de escala, parâmetro 4: tempo de escala (segundos).",
  ["Parameter 1: levelID, parameter 2: X, 3: Y, 4: Z, 5: Icon style, 6: scale multiplier, 7: scale time (seconds)."] = "Parâmetro 1: levelID, parâmetro 2: X, 3: Y, 4: Z, 5: Estilo do ícone, 6: multiplicador de escala, 7: tempo de escala (segundos).",
  ["Parameter 1: levelMapID, parameter 2: pass 1 to mask scene logic (for art)."] = "Parâmetro 1: levelMapID, parâmetro 2: passe 1 para mascarar a lógica da cena (para arte).",
  ["Parameter 1: str log level, parameter 2: int enable; e.g., error 1."] = "Parâmetro 1: nível de log str, parâmetro 2: int enable; por exemplo, erro 1.",
  ["Param 1: Work ID (remove SHARE from the corresponding work code obtained in the share interface)"] = "Parâmetro 1: ID de trabalho (remova SHARE do código de trabalho correspondente obtido na interface de compartilhamento)",
  ["Param 1: Work ID (remove SHARE from the corresponding work code obtained in the share interface), Param 2: Amount of heat to add"] = "Parâmetro 1: ID de trabalho (remova SHARE do código de trabalho correspondente obtido na interface de compartilhamento), Parâmetro 2: Quantidade de calor a ser adicionada",
  ["Parameter 1: corresponding position, parameter 2: corresponding profession character creation data ID."] = "Parâmetro 1: posição correspondente, parâmetro 2: ID de dados de criação de personagem de profissão correspondente.",
  ["Parameter 1: collectible category ID, parameter 2: added points (supports negative)."] = "Parâmetro 1: ID da categoria colecionável, parâmetro 2: pontos adicionados (suporta negativo).",
  ["Parameter 1: quantity."] = "Parâmetro 1: quantidade.",
  ["Parameter 1: inspection type (0: 3D item, 1: 3D scene), parameter 2: inspection ID (configured in inspection table), parameter 3: debug."] = "Parâmetro 1: tipo de inspeção (0: item 3D, 1: cena 3D), parâmetro 2: ID de inspeção (configurado na tabela de inspeção), parâmetro 3: depuração.",
  ["Parameter 1: state 0, 1, 2, 3; parameter 2: latency."] = "Parâmetro 1: estado 0, 1, 2, 3; parâmetro 2: latência.",
  ["Param 1: Gameplay ID (enters the 3C state for the corresponding gameplay) (used only to test the 3C state, not the entire gameplay)"] = "Parâmetro 1: ID do jogo (entra no estado 3C para o jogo correspondente) (usado apenas para testar o estado 3C, não o jogo inteiro)",
  ["Parameter 1: Target group number; Parameter 2: Target rank; Parameter 3 (optional): Target region ID, defaults to own region."] = "Parâmetro 1: Número do grupo-alvo; Parâmetro 2: Classificação alvo; Parâmetro 3 (opcional): ID da região de destino, o padrão é a própria região.",
  ["Parameter 1: invitee ID."] = "Parâmetro 1: ID do convidado.",
  ["Parameter 1: Set fixed value for next check dice, 0-restore normal, 1 to 20-fixed dice value"] = "Parâmetro 1: Definir valor fixo para o próximo dado de verificação, 0-restauração normal, 1 a 20-valor de dado fixo",
  ["Parameter 1: stage number."] = "Parâmetro 1: número do estágio.",
  ["Parameters: groupIndex teamIndex memberIndex minimum is 1"] = "Parâmetros: groupIndex teamIndex memberIndex mínimo é 1",
  ["Parameter: matchType, 3 (3v3), 4 (5v5), 5 (12v12)."] = "Parâmetro: matchType, 3 (3v3), 4 (5v5), 5 (12v12).",
  ["Parameters: true, false."] = "Parâmetros: verdadeiro, falso.",
  ["Parameters: true (enable), false (disable)."] = "Parâmetros: verdadeiro (habilitar), falso (desabilitar).",
  ["Parameter: experience value."] = "Parâmetro: valor da experiência.",
  ["Parameter: conversion quantity."] = "Parâmetro: quantidade de conversão.",
  ["Parameter: ReminderID (reminders with parameters not currently supported)."] = "Parâmetro: ReminderID (lembretes com parâmetros não suportados atualmente).",
  ["Parameter: popup ID (popups with parameters not currently supported)."] = "Parâmetro: ID do pop-up (pop-ups com parâmetros não suportados atualmente).",
  ["Parameter is true"] = "O parâmetro é verdadeiro",
  ["Parameter is tutorial GroupID."] = "O parâmetro é o tutorial GroupID.",
  ["Parameter value list"] = "Lista de valores de parâmetros",
  ["Parameters: is male character, enable clothing kawaii, enable hair kawaii."] = "Parâmetros: é personagem masculino, habilita roupas kawaii, habilita cabelo kawaii.",
  ["Parameter Name"] = "Nome do parâmetro",
  ["Parameter source mode"] = "Modo de origem do parâmetro",
  ["Parameter type list"] = "Lista de tipos de parâmetros",
  ["Enter the reference path for the blueprint effect."] = "Insira o caminho de referência para o efeito blueprint.",
  ["Parameter (1: enable, 0: disable)."] = "Parâmetro (1: habilitar, 0: desabilitar).",
  ["Parameter (LoadingPerformanceID in the world teleport table), leave blank to return to default effect."] = "Parâmetro (LoadingPerformanceID na tabela de teletransporte mundial), deixe em branco para retornar ao efeito padrão.",
  ["Parameters: in-game challenge option list, e.g., 110101, 110201, 110301, 110401, 110501."] = "Parâmetros: lista de opções de desafio no jogo, por exemplo, 110101, 110201, 110301, 110401, 110501.",
  ["Parameters: Year, Month, Day, Hour, Minute, Second."] = "Parâmetros: Ano, Mês, Dia, Hora, Minuto, Segundo.",
  ["Param: InsID of the rail"] = "Parâmetro: InsID do trilho",
  ["Parameter: player name."] = "Parâmetro: nome do jogador.",
  ["Parameters: player name, added value."] = "Parâmetros: nome do jogador, valor agregado.",
  ["Parameter: Set level"] = "Parâmetro: Definir nível",
  ["The reference image is the Storm Charm; it needs to be changed to a gold material with sunlight patterns."] = "A imagem de referência é o Storm Charm; ele precisa ser alterado para um material dourado com padrões de luz solar.",
  ["Visit"] = "Visita",
  ["Visit Statue"] = "Visite a estátua",
  ["Participating students, sign up with me—"] = "Alunos participantes, inscrevam-se comigo—",
  ["Contestant Students and Senior Student"] = "Alunos Concorrentes e Aluno Sênior",
  ["Participating Projections %s/%s"] = "Projeções Participantes %s / %s",
  ["Participation Condition"] = "Condição de Participação",
  ["Contestant Female 1"] = "Concorrente Feminino 1",
  ["Contestant Female 2"] = "Concorrente Feminino 2",
  ["Contestant Female 3"] = "Concorrente Feminino 3",
  ["Contestant Female 4"] = "Concorrente Feminino 4",
  ["Contestant Male 1"] = "Concorrente Masculino 1",
  ["Contestant Male 2"] = "Concorrente Masculino 2",
  ["Contestant Male 3"] = "Concorrente Masculino 3",
  ["Contestant Male 4"] = "Concorrente Masculino 4",
  ["Contestant"] = "Concorrente",
  ["Another month, another month of sailing is over."] = "Mais um mês, mais um mês de navegação acabou.",
  ["Another letter from a suitor... hmm? Haven't I opened this one?"] = "Outra carta de um pretendente... hmm? Eu não abri este?",
  ["Another group of lost lambs has wandered into my garden."] = "Outro grupo de cordeiros perdidos entrou no meu jardim.",
  ["Giving up on catching the thief? Let's find that child first."] = "Desistir de pegar o ladrão? Vamos encontrar aquela criança primeiro.",
  ["It's not my birthday. I think it's better to save the money, or prepare a set for Benson first."] = "Não é meu aniversário. Acho melhor economizar dinheiro ou preparar primeiro um set para Benson.",
  ["It's not like I'm attending a Ball, something plain is more appropriate."] = "Não é como se eu estivesse participando de um baile, algo simples é mais apropriado.",
  ["Something came up again?! How many times has this been, I want to break up with you!"] = "Surgiu alguma coisa de novo?! Quantas vezes já aconteceu, quero terminar com você!",
  ["You had another long dream, but it was no longer a nightmare.\n In the dream, you seemed to see a friend you hadn't met for many years,\n and you chatted together for a long time..."] = "Você teve outro longo sonho, mas não era mais um pesadelo.\n No sonho, você parecia ver um amigo que não via há muitos anos,\n e vocês conversaram por um longo tempo...",
  ["Studying in secret again. Hmph, how can there be such a devious person like you in the world?"] = "Estudando em segredo novamente. Hmph, como pode haver uma pessoa tão tortuosa como você no mundo?",
  ["Studying in secret again! We agreed to go to the lounge to play board games today."] = "Estudando em segredo novamente! Combinamos de ir ao salão jogar jogos de tabuleiro hoje.",
  ["Many more words pop up"] = "Muitas outras palavras aparecem",
  ["It's happening again... <P_Heart>(shakes head violently)</> It must be an illusion, but this is the third time this month..."] = "Está acontecendo de novo... <P_Heart> (balança a cabeça violentamente) </> Deve ser uma ilusão, mas esta é a terceira vez neste mês...",
  ["It appeared again... these words..."] = "Apareceu novamente... estas palavras...",
  ["Appear again?"] = "Aparecer de novo?",
  ["It's the same as before... but thankfully I'm okay."] = "É o mesmo de antes... mas felizmente estou bem.",
  ["Crying again? Are you going to cry like this at our wedding too?"] = "Chorando de novo? Você vai chorar assim no nosso casamento também?",
  ["Back in a nightmare again?"] = "De volta a um pesadelo de novo?",
  ["Back in the Land of Chaos again... but this place seems to be above the pond. Are the two worlds connected? How amazing..."] = "De volta à Terra do Caos novamente... mas este lugar parece estar acima do lago. Os dois mundos estão conectados? Que incrível...",
  ["Back here again, at the Central Square. I think that's enough wandering for now."] = "De volta aqui novamente, na Praça Central. Acho que já chega de vagar por enquanto.",
  ["Back in this room again... The ritual circle that caused Daisy's death wasn't an evil ritual..."] = "De volta a esta sala novamente... O círculo ritual que causou a morte de Daisy não foi um ritual maligno...",
  ["Back again? It seems you haven't had your fill yet."] = "De volta? Parece que você ainda não se satisfez.",
  ["Fighting evil again? Do you guys not work at all?"] = "Lutando contra o mal novamente? Vocês não trabalham?",
  ["Do you want me to agree to him again? Let me think..."] = "Você quer que eu concorde com ele novamente? Deixe-me pensar...",
  ["Or, would you like to take a ride later? I can book a carriage, and it's a fixed price. I don't do the kind where you haggle after getting in."] = "Ou você gostaria de dar uma volta mais tarde? Posso reservar uma carruagem e é um preço fixo. Eu não faço o tipo de barganha depois de entrar.",
  ["Or perhaps it was some evil, invincible power. I don't lean toward the latter option; for his neighbors and the nearby property values, that's even worse than a bounced check."] = "Ou talvez fosse algum poder maligno e invencível. Não me inclino para a última opção; para seus vizinhos e os valores das propriedades próximas, isso é ainda pior do que um cheque devolvido.",
  ["Grade 0 again... Extremely dangerous, must not be inquired about, must not be spread, must not be described, must not be pried into."] = "Nota 0 novamente... Extremamente perigoso, não deve ser questionado, não deve ser divulgado, não deve ser descrito, não deve ser arrombado.",
  ["Another dream... Whose dream is this?"] = "Outro sonho... De quem é esse sonho?",
  ["Another poor soul fooled by fate. I've been waiting for you here for a long time."] = "Outra pobre alma enganada pelo destino. Estou esperando por você aqui há muito tempo.",
  ["Another bell rang, and on the gray-white and cyan-black clock face, there was one more mottled hour hand."] = "Outra campainha tocou e, no mostrador do relógio branco-acinzentado e preto-ciano, havia mais um ponteiro das horas manchado.",
  ["Boating again, this is the eighth time."] = "Andando de barco novamente, esta é a oitava vez.",
  ["It's that guy from before again!"] = "É aquele cara de antes de novo!",
  ["Another puzzle... seems to be a bouquet of daisies?"] = "Outro quebra-cabeça... parece ser um buquê de margaridas?",
  ["New life again... <P_Heart>(Lowering voice)</> Rozanne, you go into the Safe House first, I'll hold him off."] = "Vida nova de novo... <P_Heart> (Voz baixa) </> Rozanne, você vai primeiro para a Casa Segura, eu vou segurá-lo.",
  ["Another newborn... (lowers voice) Rozanne, you guys head to the safe house first. I'll hold him off."] = "Outro recém-nascido... (abaixa a voz) Rozanne, vocês vão primeiro para a casa segura. Eu vou segurá-lo.",
  ["Here to ask for money again?"] = "Está aqui para pedir dinheiro de novo?",
  ["The Dragon-Hunting Gang again? Are they roaming the streets bullying people once more?"] = "A Gangue Caçadora de Dragões de novo? Eles estão vagando pelas ruas intimidando as pessoas mais uma vez?",
  ["The washroom again?"] = "O banheiro de novo?",
  ["Again... again... how many times have I said..."] = "De novo... de novo... quantas vezes eu já disse...",
  ["This kind of monster again? Must solve it quickly, can't waste too much time."] = "Esse tipo de monstro de novo? Deve resolver isso rapidamente, não pode perder muito tempo.",
  ["This feeling again... I can't move, damn it!"] = "Essa sensação de novo... não consigo me mexer, droga!",
  ["Another note?"] = "Outra nota?",
  ["Someone coming to understand again... what's the use of understanding? People won't come back to life."] = "Alguém voltando a entender... de que adianta entender? As pessoas não voltarão à vida.",
  ["Someone else is coming, maybe we should ask him."] = "Alguém está vindo, talvez devêssemos perguntar a ele.",
  ["Someone else is here for divination"] = "Alguém está aqui por adivinhação",
  ["Another unlucky soul has come to drink tea."] = "Outra alma azarada veio tomar chá.",
  ["The plague has broken out in another place, but I cannot find the source."] = "A praga estourou em outro lugar, mas não consigo encontrar a fonte.",
  ["Another new guest is coming... *huff, huff*... \n Strange... the village said, you can't do things sneakily..."] = "Outro novo convidado está chegando... *huff, huff*... \n Estranho... a vila disse, você não pode fazer as coisas sorrateiramente...",
  ["Another Sanguine fan has arrived..."] = "Mais um torcedor Sanguine chegou...",
  ["Again... will it be symmetry this time too?"] = "Novamente... será simetria desta vez também?",
  ["Another Clown? Now that's something worth watching!"] = "Outro palhaço? Isso é algo que vale a pena assistir!",
  ["Another one? If you're not buying flowers, leave quickly, or I'll call the constable."] = "Outro? Se não for comprar flores, saia rapidamente ou chamarei o policial.",
  ["It's happening again... the voice... it's calling me to turn that page again... it's the same sentence every time..."] = "Está acontecendo de novo... a voz... está me chamando para virar aquela página novamente... é sempre a mesma frase...",
  ["Here we go again, broken baskets and rotten vegetables... who did this!"] = "Lá vamos nós de novo, cestos quebrados e legumes podres... quem fez isso!",
  ["Here again? Still making futile struggles? Even if you understand a few acting principles, you can't get rid of me."] = "Aqui de novo? Ainda fazendo lutas fúteis? Mesmo que você entenda alguns princípios de atuação, não conseguirá se livrar de mim.",
  ["Are you here in Tingen for a quest again?"] = "Você está aqui em Tingen para um missão de novo?",
  ["Again? I've had enough, let's break up!"] = "De novo? Já estou farto, vamos terminar!",
  ["Hot and fresh oyster soup, drink a bowl in the morning, and be energetic all day!"] = "Sopa de ostra quente e fresca, beba uma tigela pela manhã e tenha energia o dia todo!",
  ["Also known as the \"Endless Maze.\" A rectangular gold foil strip crafted with special techniques, with one end twisted 180 degrees and connected to the other, forming a ring with only one surface."] = "Também conhecido como \"Labirinto Sem Fim\". Tira retangular de folha de ouro confeccionada com técnicas especiais, com uma extremidade torcida 180 graus e conectada à outra, formando um anel com apenas uma superfície.",
  ["Also known as a 'Demon Hunter', you gain exaggerated strength and a spirit between god and man. Capable of making potions to deal with complex situations and masking actions to interfere with divination, you are the nemesis of demons and monsters."] = "Também conhecido como ‘Caçador de Demônios’, você ganha uma força exagerada e um espírito entre Deus e o homem. Capaz de fazer poções para lidar com situações complexas e mascarar ações para interferir em adivinhação , você é o inimigo de demônios e monstros.",
  ["Also known as 'Midsummer'. A dark gold brooch shaped like a sunbird."] = "Também conhecido como 'Solstício de Verão'. Um broche de ouro escuro em forma de pássaro solar.",
  ["Also known as a psychoanalyst, able to treat or induce madness, directly influencing targets through abilities like \"Deterrence,\" \"Psychological Suggestion,\" and \"Pacify,\" grasping the most real emotions and thoughts."] = "Também conhecido como psicanalista, capaz de tratar ou induzir a loucura, influenciando diretamente os alvos através de habilidades como “Dissuasão”, “Sugestão Psicológica” e “Pacificar”, captando as emoções e pensamentos mais reais.",
  ["Cliff that guy got away again!"] = "Cliff, aquele cara fugiu de novo!",
  ["And slowly lowered his head, letting his thoughts drift toward his distant hometown."] = "E lentamente abaixou a cabeça, deixando seus pensamentos vagarem em direção à sua distante cidade natal.",
  ["Beautiful again"] = "Linda de novo",
  ["It's dirty and broken! ...Sigh, the servants I hire always run away, and some even steal the family's jewelry."] = "Está sujo e quebrado! ...Suspiro, os empregados que eu contrato sempre fogem, e alguns até roubam as joias da família.",
  ["Filming again?"] = "Filmando de novo?",
  ["See the <h>hunter</> again"] = "Veja o <h> caçador </> novamente",
  ["See Tom again"] = "Ver Tom novamente",
  ["We meet again, friend. The music here also contains echoes of the past."] = "Nos encontramos novamente, amigo. A música aqui também contém ecos do passado.",
  ["We meet again, Miss Delota."] = "Nos encontramos novamente, senhorita Delota.",
  ["Met you again, the star of the Club!"] = "Te encontrei de novo, a estrela do Clube!",
  ["It's! Night! Again!"] = "Isso é! Noite! De novo!",
  ["Throw it out! Feed it to Riel Bieber!"] = "Jogue fora! Alimente Riel Bieber!",
  ["Fork"] = "Garfo",
  ["Kill the Starlight Guard in time to pick up the Fallen Starlight!"] = "Mate o Starlight Guard a tempo de pegar a Fallen Starlight!",
  ["Switch targets to <Highlight>Filthy Cub</> in time, then push the cub under Gulu <Highlight>to be devoured by Gulu</>, thereby controlling the growth of the Hunger Value."] = "Mude os alvos para <Highlight> Filthy Cub </> a tempo e empurre o filhote para baixo de Gulu <Highlight> para ser devorado por Gulu </> , controlando assim o crescimento do Valor da Fome.",
  ["Timely release group healing or Damage Reduction skills!!"] = "Liberar oportunamente habilidades de cura em grupo ou redução de danos!!",
  ["Friend"] = "Amigo",
  ["Friendly forces"] = "Forças amigas",
  ["Allies gain <HighLight>15</> Defense, Iron Guards gain an additional <HighLight>30</> Defense; for the first <HighLight>10</> seconds of battle, gain an additional <HighLight>10%</> Defense."] = "Aliados ganham <HighLight> 15 </> de Defesa, os Guardas de Ferro ganham <HighLight> 30 </> de Defesa adicionais; durante os primeiros <HighLight> 10 </> segundos de batalha, ganhe <HighLight> 10% </> de Defesa adicional.",
  ["Allies gain <HighLight>15</> Defense, Iron Guards gain an additional <HighLight>55</> Defense; for the first <HighLight>10</> seconds of battle, gain an additional <HighLight>20%</> Defense."] = "Aliados ganham <HighLight> 15 </> de Defesa, os Guardas de Ferro ganham <HighLight> 55 </> de Defesa adicionais; durante os primeiros <HighLight> 10 </> segundos de batalha, ganhe <HighLight> 20% </> de Defesa adicional.",
  ["Allies gain <HighLight>15</> Defense, Iron Guards gain an additional <HighLight>80</> Defense; for the first <HighLight>10</> seconds of battle, gain an additional <HighLight>30%</> Defense."] = "Aliados ganham <HighLight> 15 </> de Defesa, os Guardas de Ferro ganham <HighLight> 80 </> de Defesa adicionais; durante os primeiros <HighLight> 10 </> segundos de batalha, ganhe <HighLight> 30% </> de Defesa adicional.",
  ["Allies gain <HighLight>5%</> Health bonus, Monsters gain an additional <HighLight>20%</> maximum Health bonus."] = "Aliados ganham <HighLight> 5% </> de bônus de Saúde, Monstros ganham um adicional de <HighLight> 20% </> de bônus máximo de Saúde.",
  ["Allies gain <HighLight>5%</> Health bonus, Monsters gain an additional <HighLight>40%</> maximum Health bonus."] = "Aliados ganham <HighLight> 5% </> de bônus de Saúde, Monstros ganham um adicional de <HighLight> 40% </> de bônus máximo de Saúde.",
  ["Allies gain <HighLight>5%</> Health bonus, Monsters gain an additional <HighLight>60%</> maximum Health bonus."] = "Aliados ganham <HighLight> 5% </> de bônus de Saúde, Monstros ganham um adicional de <HighLight> 60% </> de bônus máximo de Saúde.",
  ["Allies gain <HighLight>5%</> Health bonus, Monsters gain an additional <HighLight>80%</> maximum Health bonus."] = "Aliados ganham <HighLight> 5% </> de bônus de Saúde, Monstros ganham um adicional de <HighLight> 80% </> de bônus máximo de Saúde.",
  ["Friendly"] = "Amigável",
  ["Friendly? They only care about collateral. Look, I can lend you money here without any collateral."] = "Amigável? Eles só se preocupam com garantias. Olha, posso te emprestar dinheiro aqui sem qualquer garantia.",
  ["Friendly Boss"] = "Amigável Chefe",
  ["Friendliness"] = "Simpatia",
  ["The Weight of Friendship"] = "O Peso da Amizade",
  ["Ally Priority Mode"] = "Modo Prioridade Aliado",
  ["When allies receive healing effects within the domain, they gain 7.5% damage reduction, lasting for 1 second."] = "Quando aliados recebem efeitos de cura dentro do domínio, eles ganham 7,5% de redução de dano, com duração de 1 segundo.",
  ["Number of allies"] = "Número de aliados",
  ["Ally Lock Indicator Box"] = "Caixa Indicadora de Bloqueio Aliado",
  ["Ally Lock Indicator Point"] = "Ponto indicador de bloqueio de aliado",
  ["Ally Lock Indicator Line"] = "Linha Indicadora de Bloqueio Aliado",
  ["Double Chin"] = "Queixo duplo",
  ["Duo 2"] = "Dupla 2",
  ["Duo 3"] = "Dupla 3",
  ["Duo Actor 12"] = "Dupla Ator 12",
  ["Duo: Bridal Carry"] = "Duo: Transporte Nupcial",
  ["Duo: Waltz"] = "Dupla: Valsa",
  ["Duo: Hug"] = "Dupla: Abraço",
  ["Duo: Heart Gesture"] = "Duo: Gesto do Coração",
  ["Duo: Propose"] = "Dupla: Propor",
  ["Duo: Hold Hands"] = "Dupla: Dê as mãos",
  ["Duo: On the Throne"] = "Dupla: No Trono",
  ["Duo Side"] = "Lado Duo",
  ["Ride together for 30 seconds"] = "Ande juntos por 30 segundos",
  ["Double Action"] = "Dupla Ação",
  ["During dual actions, if one party is corrupted, the other has a probability of being corrupted."] = "Durante ações duplas, se uma parte for corrompida, a outra tem probabilidade de ser corrompida.",
  ["Other social emotes and actions cannot be used during a dual action."] = "Outros emotes e ações sociais não podem ser usados ​​durante uma ação dupla.",
  ["Duo Waltz (Initiator)"] = "Duo Waltz (iniciador)",
  ["Duo Waltz (Invitee)"] = "Duo Waltz (convidado)",
  ["Double Bed: Canopy"] = "Cama de Casal: Dossel",
  ["Double Bed: Walnut"] = "Cama de Casal: Nogueira",
  ["Duo Zoom Out"] = "Diminuir zoom em dupla",
  ["Two-player challenge"] = "Desafio para dois jogadores",
  ["In duo mode, you can give fragments via the [Memory Retrace] feature in the memory fragment interface, which players within the dungeon can then pick up."] = "No modo duo, você pode fornecer fragmentos por meio do recurso [Memory Retrace] na interface de fragmentos de memória, que os jogadores dentro do masmorra podem pegar.",
