  ["Ancient Evil"] = "Mal Antigo",
  ["Classical"] = "Clássico",
  ["A classic seven-foot grand piano with a bright and beautiful tone."] = "Um piano de cauda clássico de sete pés com um timbre brilhante e bonito.",
  ["Classical and Steady"] = "Clássico e constante",
  ["Classical Harp"] = "Harpa Clássica",
